// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, type(uint128).max);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        assertEq(address(c).balance, amount);
        vm.prank(actor);
        c.withdrawAll();

        assertTrue(address(c).balance == 0);
    }
}
